-- Private AI Patient Card - initial schema (ETAP 1)
-- All timestamps are stored as timestamptz (UTC on the server).
-- UUIDs are generated by the application; database defaults are a safety net.

CREATE TABLE users (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email         VARCHAR(320) NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    display_name  VARCHAR(120) NOT NULL,
    enabled       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uk_users_email UNIQUE (email),
    CONSTRAINT ck_users_email_not_blank CHECK (btrim(email) <> ''),
    CONSTRAINT ck_users_display_name_not_blank CHECK (btrim(display_name) <> '')
);

CREATE TABLE patient_profiles (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    first_name   VARCHAR(100),
    last_name    VARCHAR(100),
    date_of_birth DATE,
    sex          VARCHAR(16),
    height_cm    NUMERIC(5, 1),
    weight_kg    NUMERIC(5, 1),
    blood_type   VARCHAR(16),
    notes        VARCHAR(10000),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uk_patient_profiles_user UNIQUE (user_id),
    CONSTRAINT ck_patient_height CHECK (height_cm IS NULL OR (height_cm > 0 AND height_cm < 300)),
    CONSTRAINT ck_patient_weight CHECK (weight_kg IS NULL OR (weight_kg > 0 AND weight_kg < 1000)),
    CONSTRAINT ck_patient_sex CHECK (sex IS NULL OR sex IN ('FEMALE', 'MALE', 'OTHER', 'UNKNOWN')),
    CONSTRAINT ck_patient_blood_type CHECK (blood_type IS NULL OR blood_type IN ('A_POSITIVE', 'A_NEGATIVE', 'B_POSITIVE', 'B_NEGATIVE', 'AB_POSITIVE', 'AB_NEGATIVE', 'ZERO_POSITIVE', 'ZERO_NEGATIVE', 'UNKNOWN'))
);

-- One counter row per patient. Image numbers are allocated in a transaction
-- after locking this row (SELECT ... FOR UPDATE), never with COUNT(*) + 1.
CREATE TABLE patient_image_counters (
    patient_id       UUID PRIMARY KEY REFERENCES patient_profiles (id) ON DELETE CASCADE,
    last_image_number BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT ck_image_counter_non_negative CHECK (last_image_number >= 0)
);

CREATE TABLE doctors (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id    UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    first_name    VARCHAR(100) NOT NULL,
    last_name     VARCHAR(100) NOT NULL,
    specialty     VARCHAR(120),
    facility_name VARCHAR(200),
    phone         VARCHAR(50),
    email         VARCHAR(320),
    address       VARCHAR(500),
    notes         VARCHAR(10000),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_doctors_names_not_blank CHECK (btrim(first_name) <> '' AND btrim(last_name) <> '')
);

CREATE INDEX idx_doctors_patient ON doctors (patient_id);
CREATE INDEX idx_doctors_patient_name ON doctors (patient_id, last_name, first_name);

CREATE TABLE medical_documents (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id        UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    document_type     VARCHAR(40) NOT NULL,
    title             VARCHAR(200) NOT NULL,
    description       VARCHAR(10000),
    original_filename VARCHAR(255) NOT NULL,
    storage_key       VARCHAR(500) NOT NULL,
    mime_type         VARCHAR(150) NOT NULL,
    file_size_bytes   BIGINT NOT NULL,
    sha256_checksum   VARCHAR(64) NOT NULL,
    document_date     DATE,
    uploaded_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    processing_status VARCHAR(32) NOT NULL DEFAULT 'PENDING',
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uk_documents_storage_key UNIQUE (storage_key),
    CONSTRAINT ck_documents_size CHECK (file_size_bytes > 0),
    CONSTRAINT ck_documents_checksum CHECK (sha256_checksum ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_documents_processing_status CHECK (processing_status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'NOT_REQUIRED'))
);

CREATE INDEX idx_documents_patient_uploaded ON medical_documents (patient_id, uploaded_at DESC);
CREATE INDEX idx_documents_patient_type ON medical_documents (patient_id, document_type);

CREATE TABLE medical_conditions (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id          UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    name                VARCHAR(200) NOT NULL,
    description         VARCHAR(10000),
    status              VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    onset_date          DATE,
    resolved_date       DATE,
    source_document_id  UUID REFERENCES medical_documents (id) ON DELETE SET NULL,
    origin              VARCHAR(32) NOT NULL DEFAULT 'PATIENT_REPORTED',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_conditions_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT ck_conditions_status CHECK (status IN ('ACTIVE', 'IN_REMISSION', 'RESOLVED', 'SUSPECTED')),
    CONSTRAINT ck_conditions_origin CHECK (origin IN ('PATIENT_REPORTED', 'CLINICIAN_DOCUMENTED', 'IMPORTED')),
    CONSTRAINT ck_conditions_dates CHECK (onset_date IS NULL OR resolved_date IS NULL OR resolved_date >= onset_date)
);

CREATE INDEX idx_conditions_patient_status ON medical_conditions (patient_id, status);
CREATE INDEX idx_conditions_source_document ON medical_conditions (source_document_id);

CREATE TABLE allergies (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id    UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    substance     VARCHAR(200) NOT NULL,
    reaction      VARCHAR(10000),
    severity      VARCHAR(32) NOT NULL DEFAULT 'UNKNOWN',
    status        VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    diagnosed_at  DATE,
    notes         VARCHAR(10000),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_allergies_substance_not_blank CHECK (btrim(substance) <> ''),
    CONSTRAINT ck_allergies_severity CHECK (severity IN ('MILD', 'MODERATE', 'SEVERE', 'LIFE_THREATENING', 'UNKNOWN')),
    CONSTRAINT ck_allergies_status CHECK (status IN ('ACTIVE', 'RESOLVED', 'SUSPECTED'))
);

CREATE INDEX idx_allergies_patient_status ON allergies (patient_id, status);

CREATE TABLE symptoms (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id    UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    title         VARCHAR(200) NOT NULL,
    description   VARCHAR(10000),
    body_location VARCHAR(120),
    severity      SMALLINT,
    started_at    TIMESTAMPTZ,
    ended_at      TIMESTAMPTZ,
    observed_at   TIMESTAMPTZ NOT NULL,
    status        VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_symptoms_title_not_blank CHECK (btrim(title) <> ''),
    CONSTRAINT ck_symptoms_severity CHECK (severity IS NULL OR (severity BETWEEN 1 AND 10)),
    CONSTRAINT ck_symptoms_status CHECK (status IN ('ACTIVE', 'RESOLVED', 'MONITORING')),
    CONSTRAINT ck_symptoms_dates CHECK (started_at IS NULL OR ended_at IS NULL OR ended_at >= started_at)
);

CREATE INDEX idx_symptoms_patient_observed ON symptoms (patient_id, observed_at DESC);
CREATE INDEX idx_symptoms_patient_status ON symptoms (patient_id, status);

CREATE TABLE medications (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id            UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    name                  VARCHAR(200) NOT NULL,
    active_ingredient     VARCHAR(200),
    strength              VARCHAR(50),
    dosage_form           VARCHAR(80),
    prescribed_dose       VARCHAR(100),
    route                 VARCHAR(80),
    frequency             VARCHAR(120),
    instructions          VARCHAR(10000),
    start_date            DATE,
    end_date              DATE,
    prescribing_doctor_id UUID REFERENCES doctors (id) ON DELETE SET NULL,
    status                VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    notes                 VARCHAR(10000),
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_medications_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT ck_medications_status CHECK (status IN ('ACTIVE', 'PAUSED', 'STOPPED', 'COMPLETED')),
    CONSTRAINT ck_medications_dates CHECK (start_date IS NULL OR end_date IS NULL OR end_date >= start_date)
);

CREATE INDEX idx_medications_patient_status ON medications (patient_id, status);
CREATE INDEX idx_medications_prescribing_doctor ON medications (prescribing_doctor_id);

CREATE TABLE medication_intake_logs (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    medication_id UUID NOT NULL REFERENCES medications (id) ON DELETE CASCADE,
    scheduled_at  TIMESTAMPTZ,
    taken_at      TIMESTAMPTZ,
    amount        NUMERIC(10, 3),
    unit          VARCHAR(40),
    status        VARCHAR(16) NOT NULL,
    notes         VARCHAR(10000),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_intake_status CHECK (status IN ('TAKEN', 'SKIPPED', 'UNKNOWN')),
    CONSTRAINT ck_intake_amount CHECK (amount IS NULL OR amount > 0)
);

CREATE INDEX idx_intake_medication_scheduled ON medication_intake_logs (medication_id, scheduled_at DESC);
CREATE INDEX idx_intake_medication_taken ON medication_intake_logs (medication_id, taken_at DESC);

CREATE TABLE appointments (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id      UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    doctor_id       UUID REFERENCES doctors (id) ON DELETE SET NULL,
    scheduled_at    TIMESTAMPTZ NOT NULL,
    ended_at        TIMESTAMPTZ,
    location        VARCHAR(300),
    reason          VARCHAR(10000) NOT NULL,
    status          VARCHAR(32) NOT NULL DEFAULT 'SCHEDULED',
    notes           VARCHAR(10000),
    recommendations VARCHAR(10000),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_appointments_reason_not_blank CHECK (btrim(reason) <> ''),
    CONSTRAINT ck_appointments_status CHECK (status IN ('SCHEDULED', 'COMPLETED', 'CANCELLED', 'MISSED')),
    CONSTRAINT ck_appointments_dates CHECK (ended_at IS NULL OR ended_at >= scheduled_at)
);

CREATE INDEX idx_appointments_patient_scheduled ON appointments (patient_id, scheduled_at DESC);
CREATE INDEX idx_appointments_doctor ON appointments (doctor_id);

CREATE TABLE measurements (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id      UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    type            VARCHAR(40) NOT NULL,
    value           NUMERIC(12, 3) NOT NULL,
    secondary_value NUMERIC(12, 3),
    unit            VARCHAR(30) NOT NULL,
    measured_at     TIMESTAMPTZ NOT NULL,
    source          VARCHAR(40) NOT NULL DEFAULT 'MANUAL',
    notes           VARCHAR(10000),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_measurements_value CHECK (value >= 0),
    CONSTRAINT ck_measurements_secondary CHECK (secondary_value IS NULL OR secondary_value >= 0),
    CONSTRAINT ck_measurements_type CHECK (type IN ('BLOOD_PRESSURE', 'HEART_RATE', 'WEIGHT', 'TEMPERATURE', 'GLUCOSE', 'OXYGEN_SATURATION', 'OTHER')),
    CONSTRAINT ck_measurements_source CHECK (source IN ('MANUAL', 'DEVICE', 'IMPORTED', 'UNKNOWN'))
);

CREATE INDEX idx_measurements_patient_type_date ON measurements (patient_id, type, measured_at DESC);
CREATE INDEX idx_measurements_patient_date ON measurements (patient_id, measured_at DESC);

CREATE TABLE medical_images (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id          UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    symptom_id          UUID REFERENCES symptoms (id) ON DELETE SET NULL,
    document_id         UUID REFERENCES medical_documents (id) ON DELETE SET NULL,
    image_number        BIGINT NOT NULL,
    title               VARCHAR(200),
    description         VARCHAR(10000),
    category            VARCHAR(40) NOT NULL DEFAULT 'OTHER',
    original_filename   VARCHAR(255) NOT NULL,
    storage_key         VARCHAR(500) NOT NULL,
    mime_type           VARCHAR(150) NOT NULL,
    file_size_bytes     BIGINT NOT NULL,
    width_px            INTEGER,
    height_px           INTEGER,
    sha256_checksum     VARCHAR(64) NOT NULL,
    captured_at         TIMESTAMPTZ,
    uploaded_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    sequence_number     INTEGER,
    ai_processing_status VARCHAR(32) NOT NULL DEFAULT 'PENDING',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uk_images_storage_key UNIQUE (storage_key),
    CONSTRAINT uk_images_patient_number UNIQUE (patient_id, image_number),
    CONSTRAINT ck_images_number_positive CHECK (image_number > 0),
    CONSTRAINT ck_images_size CHECK (file_size_bytes > 0),
    CONSTRAINT ck_images_checksum CHECK (sha256_checksum ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_images_category CHECK (category IN ('SKIN', 'INJURY', 'MEDICATION_PACKAGE', 'DOCUMENT', 'OTHER')),
    CONSTRAINT ck_images_ai_status CHECK (ai_processing_status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'NOT_REQUIRED')),
    CONSTRAINT ck_images_dimensions CHECK ((width_px IS NULL OR width_px > 0) AND (height_px IS NULL OR height_px > 0))
);

CREATE INDEX idx_images_patient_uploaded ON medical_images (patient_id, uploaded_at DESC);
CREATE INDEX idx_images_patient_number ON medical_images (patient_id, image_number);
CREATE INDEX idx_images_symptom ON medical_images (symptom_id);
CREATE INDEX idx_images_document ON medical_images (document_id);

CREATE TABLE image_ai_analyses (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    image_id           UUID NOT NULL REFERENCES medical_images (id) ON DELETE CASCADE,
    model_name         VARCHAR(150) NOT NULL,
    model_version      VARCHAR(100),
    prompt_version     VARCHAR(50) NOT NULL,
    analysis_text      VARCHAR(50000) NOT NULL,
    extracted_metadata JSONB,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_image_analyses_image ON image_ai_analyses (image_id, created_at DESC);

CREATE TABLE medical_document_extractions (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    document_id       UUID NOT NULL REFERENCES medical_documents (id) ON DELETE CASCADE,
    extracted_text    VARCHAR(50000),
    extraction_method VARCHAR(80) NOT NULL,
    model_name        VARCHAR(150),
    processing_status VARCHAR(32) NOT NULL DEFAULT 'PENDING',
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_document_extractions_status CHECK (processing_status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED'))
);

CREATE INDEX idx_document_extractions_document ON medical_document_extractions (document_id, created_at DESC);

CREATE TABLE chat_conversations (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    title      VARCHAR(200) NOT NULL DEFAULT 'Nowa rozmowa',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_conversations_title_not_blank CHECK (btrim(title) <> '')
);

CREATE INDEX idx_conversations_patient_updated ON chat_conversations (patient_id, updated_at DESC);

CREATE TABLE chat_messages (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_id UUID NOT NULL REFERENCES chat_conversations (id) ON DELETE CASCADE,
    role            VARCHAR(16) NOT NULL,
    content         VARCHAR(20000) NOT NULL,
    model_name      VARCHAR(150),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_chat_messages_role CHECK (role IN ('USER', 'ASSISTANT', 'SYSTEM')),
    CONSTRAINT ck_chat_messages_content_not_blank CHECK (btrim(content) <> '')
);

CREATE INDEX idx_chat_messages_conversation_created ON chat_messages (conversation_id, created_at);

CREATE TABLE ai_message_sources (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    message_id            UUID NOT NULL REFERENCES chat_messages (id) ON DELETE CASCADE,
    source_type           VARCHAR(32) NOT NULL,
    source_id             UUID NOT NULL,
    relevance_description VARCHAR(10000),
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_ai_sources_type CHECK (source_type IN ('IMAGE', 'DOCUMENT', 'SYMPTOM', 'MEDICATION', 'APPOINTMENT', 'MEASUREMENT', 'CONDITION'))
);

CREATE INDEX idx_ai_sources_message ON ai_message_sources (message_id);
CREATE INDEX idx_ai_sources_polymorphic ON ai_message_sources (source_type, source_id);

CREATE TABLE ai_processing_jobs (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id    UUID NOT NULL REFERENCES patient_profiles (id) ON DELETE CASCADE,
    resource_type VARCHAR(40) NOT NULL,
    resource_id   UUID NOT NULL,
    status        VARCHAR(32) NOT NULL DEFAULT 'PENDING',
    model_name    VARCHAR(150),
    error_message VARCHAR(10000),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at    TIMESTAMPTZ,
    completed_at  TIMESTAMPTZ,
    CONSTRAINT ck_ai_jobs_status CHECK (status IN ('PENDING', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED')),
    CONSTRAINT ck_ai_jobs_resource_type CHECK (resource_type IN ('IMAGE', 'DOCUMENT'))
);

CREATE INDEX idx_ai_jobs_patient_status ON ai_processing_jobs (patient_id, status);
CREATE INDEX idx_ai_jobs_resource ON ai_processing_jobs (resource_type, resource_id);

-- Refresh tokens are opaque random values. Only their SHA-256 hash is stored.
CREATE TABLE refresh_tokens (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash VARCHAR(64) NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uk_refresh_tokens_hash UNIQUE (token_hash),
    CONSTRAINT ck_refresh_tokens_hash CHECK (token_hash ~ '^[0-9a-f]{64}$')
);

CREATE INDEX idx_refresh_tokens_user ON refresh_tokens (user_id);
CREATE INDEX idx_refresh_tokens_expiry ON refresh_tokens (expires_at);
